1	package metrics
2	
3	import (
4		"errors"
5		"math"
6		"sort"
7		"strings"
8		"time"
9	)
10	
11	// Aggregation limits: at most this many segments cover one query window, and
12	// the response must not contain more than this many series-segment pairs.
13	// Requests beyond either bound are rejected rather than truncated.
14	const (
15		MaxAggregateSegments       = 10000
16		MaxAggregateSeriesSegments = 100000
17	)
18	
19	// AggregateQuery selects samples by exact metric name, optional exact service,
20	// and the same label conditions event queries use, over the half-open window
21	// [Since, Until), split from Since into intervals of Step.
22	type AggregateQuery struct {
23		Name    string
24		Service string
25		Since   time.Time
26		Until   time.Time
27		Step    time.Duration
28		Labels  map[string]string
29	}
30	
31	// AggregateSegment is one aligned slice of one series: the UTC boundaries,
32	// how many samples fall in it, and the cumulative-counter delta attributed to
33	// it. Segments without samples carry a zero count and delta.
34	type AggregateSegment struct {
35		Start time.Time
36		End   time.Time
37		Count int
38		Delta float64
39	}
40	
41	// AggregateSeries is one matching series' complete segment set. Labels is nil
42	// when the series has none.
43	type AggregateSeries struct {
44		Service  string
45		Labels   map[string]string
46		Segments []AggregateSegment
47	}
48	
49	// Query problems aggregation can hit. The HTTP layer maps each to a status.
50	var (
51		// ErrAggregateStep reports a non-positive step.
52		ErrAggregateStep = errors.New("aggregate step must be positive")
53		// ErrAggregateWindow reports a start not strictly before its end.
54		ErrAggregateWindow = errors.New("aggregate window must start before it ends")
55		// ErrTooManySegments reports a window needing more than
56		// MaxAggregateSegments segments.
57		ErrTooManySegments = errors.New("aggregate window requires too many segments")
58		// ErrTooManySeriesSegments reports a response holding more than
59		// MaxAggregateSeriesSegments series-segment pairs.
60		ErrTooManySeriesSegments = errors.New("aggregate covers too many series segments")
61		// ErrDeltaNotFinite reports increments whose sum overflows to a
62		// non-finite value; the whole query fails rather than returning Inf/NaN.
63		ErrDeltaNotFinite = errors.New("aggregate delta total is not a finite number")
64	)
65	
66	// Aggregate computes per-series sample counts and cumulative deltas over the
67	// query window using a single read of the store, so every series and segment
68	// reflects one committed snapshot. Late arrivals are bucketed by their own
69	// sample time, so an unchanged dataset always yields the same result
70	// regardless of ingestion order.
71	func (s *Store) Aggregate(query AggregateQuery) ([]AggregateSeries, error) {
72		segments, err := ValidateAggregateQuery(query)
73		if err != nil {
74			return nil, err
75		}
76	
77		name := strings.TrimSpace(query.Name)
78		service := strings.TrimSpace(query.Service)
79	
80		s.mu.RLock()
81		defer s.mu.RUnlock()
82	
83		// Select the matching series that actually have a sample in the
84		// half-open window, in a stable order (service, then full label set).
85		keys := make([]seriesKey, 0, len(s.series))
86		for key, state := range s.series {
87			if key.name != name {
88				continue
89			}
90			if service != "" && key.service != service {
91				continue
92			}
93			if !labelsMatch(state.labels, query.Labels) {
94				continue
95			}
96			if !state.hasPointBetween(query.Since, query.Until) {
97				continue
98			}
99			keys = append(keys, key)
100		}
101		sort.Slice(keys, func(i, j int) bool {
102			if keys[i].service != keys[j].service {
103				return keys[i].service < keys[j].service
104			}
105			return keys[i].labels < keys[j].labels
106		})
107	
108		if len(keys)*len(segments) > MaxAggregateSeriesSegments {
109			return nil, ErrTooManySeriesSegments
110		}
111	
112		out := make([]AggregateSeries, 0, len(keys))
113		var grandTotal float64
114		for _, key := range keys {
115			state := s.series[key]
116			seriesSegs := append([]AggregateSegment(nil), segments...)
117			total, err := fillSeries(seriesSegs, state.points, query)
118			if err != nil {
119				return nil, err
120			}
121			grandTotal += total
122			if !isFinite(grandTotal) {
123				return nil, ErrDeltaNotFinite
124			}
125			out = append(out, AggregateSeries{
126				Service:  key.service,
127				Labels:   state.labels,
128				Segments: seriesSegs,
129			})
130		}
131		return out, nil
132	}
133	
134	// labelsMatch reports whether a series' full label set satisfies every
135	// condition. A series missing a conditioned label never matches, and
136	// comparison is case-sensitive on names and values.
137	func labelsMatch(labels, conditions map[string]string) bool {
138		for name, want := range conditions {
139			got, ok := labels[name]
140			if !ok || got != want {
141				return false
142			}
143		}
144		return true
145	}
146	
147	// ValidateAggregateQuery enforces a positive step, a strictly increasing
148	// half-open window, and the segment bound, then returns the segment skeleton
149	// (UTC-relative boundaries are the caller's job at rendering time).
150	func ValidateAggregateQuery(query AggregateQuery) ([]AggregateSegment, error) {
151		if query.Step <= 0 {
152			return nil, ErrAggregateStep
153		}
154		length := query.Until.Sub(query.Since)
155		if length <= 0 {
156			return nil, ErrAggregateWindow
157		}
158		count := int64(length / query.Step)
159		if length%query.Step != 0 {
160			count++
161		}
162		if count > MaxAggregateSegments {
163			return nil, ErrTooManySegments
164		}
165	
166		out := make([]AggregateSegment, count)
167		for i := range out {
168			start := query.Since.Add(query.Step * time.Duration(i))
169			end := start.Add(query.Step)
170			if end.After(query.Until) {
171				end = query.Until
172			}
173			out[i] = AggregateSegment{Start: start, End: end}
174		}
175		return out, nil
176	}
177	
178	// hasPointBetween reports whether any point falls in [since, until).
179	func (st *seriesState) hasPointBetween(since, until time.Time) bool {
180		idx := sort.Search(len(st.points), func(i int) bool {
181			return !st.points[i].at.Before(since)
182		})
183		return idx < len(st.points) && st.points[idx].at.Before(until)
184	}
185	
186	// fillSeries counts samples per segment and attributes cumulative deltas.
187	// The nearest sample strictly before the window start acts as the first
188	// in-window sample's predecessor; a sample with no predecessor anywhere
189	// contributes no delta. A value that does not move backwards contributes the
190	// difference; a backwards move is a counter reset and contributes the current
191	// value. Every delta lands in the segment containing the later sample; the
192	// sample at the window end never participates. It returns the series' total
193	// delta so the caller can fail the whole query when no finite grand total
194	// exists.
195	func fillSeries(segments []AggregateSegment, points []point, query AggregateQuery) (float64, error) {
196		step := query.Step
197	
198		// First point at or after the window start.
199		first := sort.Search(len(points), func(i int) bool {
200			return !points[i].at.Before(query.Since)
201		})
202	
203		var prevValue, total float64
204		hasPrev := false
205		if first > 0 {
206			prevValue = points[first-1].value
207			hasPrev = true
208		}
209	
210		for _, p := range points[first:] {
211			if !p.at.Before(query.Until) {
212				break // at == until and anything later is excluded
213			}
214			idx := int(p.at.Sub(query.Since) / step)
215			if idx >= len(segments) {
216				idx = len(segments) - 1 // defensive; excluded end keeps this in range
217			}
218			segments[idx].Count++
219	
220			var delta float64
221			if hasPrev {
222				if p.value >= prevValue {
223					delta = p.value - prevValue
224				} else {
225					delta = p.value // counter reset
226				}
227				segments[idx].Delta += delta
228				if !isFinite(segments[idx].Delta) {
229					return 0, ErrDeltaNotFinite
230				}
231				total += delta
232				if !isFinite(total) {
233					return 0, ErrDeltaNotFinite
234				}
235			}
236			prevValue = p.value
237			hasPrev = true
238		}
239		return total, nil
240	}
241	
242	func isFinite(v float64) bool {
243		return !math.IsNaN(v) && !math.IsInf(v, 0)
244	}
