1	package metrics
2	
3	import (
4		"reflect"
5		"strconv"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	// Regression coverage for the relationship between whole-batch metric
12	// ingestion (POST /metrics) and cumulative aggregation
13	// (GET /metrics/aggregate): every aggregate response must be computed from
14	// one committed snapshot. The returned series set, every segment's sample
15	// count, and every segment delta must all belong to the same committed
16	// dataset — never a mix where one series already counts a batch while another
17	// series still shows its pre-batch result.
18	//
19	// The discriminating scenario: one metric name "requests" in service "svc"
20	// with three label series. Two series (labels a=1 and a=2) already exist;
21	// one batch supplements both, creates a third previously absent series
22	// (a=3), and carries late historical samples — including samples strictly
23	// before the query start, which rewrite the predecessor used by the first
24	// in-window sample (a=1's predecessor moves; a=2's first sample gains one it
25	// did not have). The window spans three one-minute segments, and a sample per
26	// existing series sits exactly at the query end (both excluded). The batch
27	// body is deliberately shuffled so predecessor/delta correctness can only
28	// come from the samples' own timestamps, not their batch order.
29	//
30	// Window [10:00:00, 10:03:00), step 60s. Cumulative readings (series keyed
31	// by label a), all monotonic within a series:
32	//
33	//	a=1: 09:57=90 (late), 09:58=100 (seed), 09:59=199 (late),
34	//	     10:00:30=200 (seed), 10:01:30=201, 10:03:00=999 (excluded)
35	//	a=2: 09:58=20 (late), 09:59=180 (late), 10:00:30=200 (seed),
36	//	     10:02:30=223, 10:03:00=999 (excluded)
37	//	a=3: 09:59=5 (late), 10:01:30=50, 10:02:30=60
38	//
39	// Before the batch a=1/a=2 each hold one in-window point. The pre-batch
40	// total delta is 100 and the post-batch total delta is also 100
41	// (a=1:2, a=2:43, a=3:55), so a check that only sums every series' deltas
42	// cannot distinguish the two states; the per-series, per-segment vectors do.
43	
44	func aggScenarioAnchor() time.Time {
45		return time.Date(2026, 10, 1, 10, 0, 0, 0, time.UTC)
46	}
47	
48	func aggScenarioQuery() AggregateQuery {
49		t0 := aggScenarioAnchor()
50		return AggregateQuery{
51			Name:  "requests",
52			Since: t0,
53			Until: t0.Add(3 * time.Minute),
54			Step:  time.Minute,
55		}
56	}
57	
58	// scenarioSeedSamples are the pre-existing readings: one in-window point per
59	// existing series, plus a predecessor for series a=1. Series a=2's in-window
60	// point is its first sample overall (no predecessor yet).
61	func scenarioSeedSamples() []Sample {
62		t0 := aggScenarioAnchor()
63		return []Sample{
64			{ID: "seed-pre-1", Service: "svc", Name: "requests", At: t0.Add(-2 * time.Minute), Value: 100, Labels: map[string]string{"a": "1"}},
65			{ID: "seed-a1", Service: "svc", Name: "requests", At: t0.Add(30 * time.Second), Value: 200, Labels: map[string]string{"a": "1"}},
66			{ID: "seed-a2", Service: "svc", Name: "requests", At: t0.Add(30 * time.Second), Value: 200, Labels: map[string]string{"a": "2"}},
67		}
68	}
69	
70	// scenarioBatchSamples is the whole batch under test, shuffled on purpose:
71	// points at the query end, the brand-new series, late pre-window
72	// predecessors (one of them earlier than the stored predecessor), in-window
73	// supplements, and more late history. Ordering must never affect the result.
74	func scenarioBatchSamples() []Sample {
75		t0 := aggScenarioAnchor()
76		return []Sample{
77			{ID: "new-end-1", Service: "svc", Name: "requests", At: t0.Add(3 * time.Minute), Value: 999, Labels: map[string]string{"a": "1"}},
78			{ID: "new-a3-1", Service: "svc", Name: "requests", At: t0.Add(90 * time.Second), Value: 50, Labels: map[string]string{"a": "3"}},
79			{ID: "new-nearpre-1", Service: "svc", Name: "requests", At: t0.Add(-1 * time.Minute), Value: 199, Labels: map[string]string{"a": "1"}},
80			{ID: "new-a1-2", Service: "svc", Name: "requests", At: t0.Add(90 * time.Second), Value: 201, Labels: map[string]string{"a": "1"}},
81			{ID: "new-farpre-2", Service: "svc", Name: "requests", At: t0.Add(-2 * time.Minute), Value: 20, Labels: map[string]string{"a": "2"}},
82			{ID: "new-a2-1", Service: "svc", Name: "requests", At: t0.Add(150 * time.Second), Value: 223, Labels: map[string]string{"a": "2"}},
83			{ID: "new-farpre-1", Service: "svc", Name: "requests", At: t0.Add(-3 * time.Minute), Value: 90, Labels: map[string]string{"a": "1"}},
84			{ID: "new-nearpre-2", Service: "svc", Name: "requests", At: t0.Add(-1 * time.Minute), Value: 180, Labels: map[string]string{"a": "2"}},
85			{ID: "new-a3-0", Service: "svc", Name: "requests", At: t0.Add(-1 * time.Minute), Value: 5, Labels: map[string]string{"a": "3"}},
86			{ID: "new-end-2", Service: "svc", Name: "requests", At: t0.Add(3 * time.Minute), Value: 999, Labels: map[string]string{"a": "2"}},
87			{ID: "new-a3-2", Service: "svc", Name: "requests", At: t0.Add(150 * time.Second), Value: 60, Labels: map[string]string{"a": "3"}},
88		}
89	}
90	
91	// scenarioConflictBatchSamples are the valid batch samples plus one sample
92	// with a brand-new id that claims an already stored (series, instant) point:
93	// series a=1 at 10:00:30 already belongs to seed-a1. The conflict must
94	// reject the whole submission before anything is persisted.
95	func scenarioConflictBatchSamples() []Sample {
96		conflict := append([]Sample(nil), scenarioBatchSamples()...)
97		t0 := aggScenarioAnchor()
98		conflict = append(conflict, Sample{
99			ID:      "clash-a1",
100			Service: "svc",
101			Name:    "requests",
102			At:      t0.Add(30 * time.Second),
103			Value:   201,
104			Labels:  map[string]string{"a": "1"},
105		})
106		return conflict
107	}
108	
109	// Expected segment vectors (three one-minute segments in window order), one
110	// entry per present series. The pre- and post-batch grand totals both equal
111	// 100 even though every per-series/per-segment value moves, which is exactly
112	// why the snapshot check must compare the whole structured response.
113	var (
114		beforeCounts = map[string][]int{
115			"1": {1, 0, 0},
116			"2": {1, 0, 0},
117		}
118		beforeDeltas = map[string][]float64{
119			"1": {100, 0, 0}, // 200 - predecessor 100
120			"2": {0, 0, 0},   // first sample overall: no predecessor
121		}
122		afterCounts = map[string][]int{
123			"1": {1, 1, 0},
124			"2": {1, 0, 1},
125			"3": {0, 1, 1},
126		}
127		afterDeltas = map[string][]float64{
128			"1": {1, 1, 0},   // (200-199), (201-200); end sample excluded
129			"2": {20, 0, 23}, // (200-180), (223-200); end sample excluded
130			"3": {0, 45, 10}, // first in-window 50 - predecessor 5, then 60-50
131		}
132	)
133	
134	func assertScenarioResult(t *testing.T, got []AggregateSeries, wantSeries []string,
135		wantCounts map[string][]int, wantDeltas map[string][]float64) {
136		t.Helper()
137		if len(got) != len(wantSeries) {
138			t.Fatalf("series set = %d (%v), want %v", len(got), seriesNames(got), wantSeries)
139		}
140		t0 := aggScenarioAnchor()
141		for i, name := range wantSeries {
142			series := got[i]
143			if series.Service != "svc" || series.Labels["a"] != name {
144				t.Fatalf("series %d = service=%q labels=%v, want a=%q (ordered a=1,a=2,a=3)",
145					i, series.Service, series.Labels, name)
146			}
147			if len(series.Segments) != 3 {
148				t.Fatalf("series a=%s segments = %d, want 3", name, len(series.Segments))
149			}
150			for j, seg := range series.Segments {
151				wantStart := t0.Add(time.Duration(j) * time.Minute)
152				wantEnd := wantStart.Add(time.Minute)
153				if !seg.Start.Equal(wantStart) || !seg.End.Equal(wantEnd) {
154					t.Fatalf("series a=%s seg %d bounds = %s..%s, want %s..%s",
155						name, j, seg.Start, seg.End, wantStart, wantEnd)
156				}
157				if seg.Count != wantCounts[name][j] {
158					t.Fatalf("series a=%s seg %d count = %d, want %d (whole result: %s)",
159						name, j, seg.Count, wantCounts[name][j], summarizeAggregate(got))
160				}
161				if seg.Delta != wantDeltas[name][j] {
162					t.Fatalf("series a=%s seg %d delta = %v, want %v (whole result: %s)",
163						name, j, seg.Delta, wantDeltas[name][j], summarizeAggregate(got))
164				}
165			}
166		}
167	}
168	
169	func seriesNames(got []AggregateSeries) []string {
170		names := make([]string, 0, len(got))
171		for _, s := range got {
172			names = append(names, s.Labels["a"])
173		}
174		return names
175	}
176	
177	// summarizeAggregate renders counts/deltas per series so a splice failure
178	// shows every series and segment, not just the first mismatch.
179	func summarizeAggregate(got []AggregateSeries) string {
180		out := ""
181		for _, s := range got {
182			out += "a=" + s.Labels["a"] + "{"
183			for i, seg := range s.Segments {
184				if i > 0 {
185					out += " "
186				}
187				out += "c=" + strconv.Itoa(seg.Count) + ",d=" + strconv.FormatFloat(seg.Delta, 'g', -1, 64)
188			}
189			out += "} "
190		}
191		return out
192	}
193	
194	func TestAggregateScenarioBeforeAndAfterWholeBatch(t *testing.T) {
195		s := NewStore()
196		query := aggScenarioQuery()
197		if _, err := s.Ingest(scenarioSeedSamples(), nil); err != nil {
198			t.Fatalf("seed: %v", err)
199		}
200	
201		before, err := s.Aggregate(query)
202		if err != nil {
203			t.Fatalf("aggregate before: %v", err)
204		}
205		assertScenarioResult(t, before, []string{"1", "2"}, beforeCounts, beforeDeltas)
206	
207		result, err := s.Ingest(scenarioBatchSamples(), noopCommit)
208		if err != nil {
209			t.Fatalf("ingest batch: %v", err)
210		}
211		if result.Created != 11 || result.Replayed != 0 {
212			t.Fatalf("batch result = %+v, want created=11", result)
213		}
214	
215		// Once the successful ingestion has returned, the same query must show
216		// the complete post-submission dataset across every series and segment.
217		after, err := s.Aggregate(query)
218		if err != nil {
219			t.Fatalf("aggregate after: %v", err)
220		}
221		assertScenarioResult(t, after, []string{"1", "2", "3"}, afterCounts, afterDeltas)
222	
223		// Timestamps, not batch order, determine predecessor readings: replaying
224		// the identical (shuffled) batch stores nothing and changes nothing.
225		replay, err := s.Ingest(scenarioBatchSamples(), noopCommit)
226		if err != nil {
227			t.Fatalf("replay batch: %v", err)
228		}
229		if replay.Created != 0 || replay.Replayed != 11 {
230			t.Fatalf("replay result = %+v, want replayed=11", replay)
231		}
232		again, err := s.Aggregate(query)
233		if err != nil {
234			t.Fatalf("aggregate after replay: %v", err)
235		}
236		if !reflect.DeepEqual(again, after) {
237			t.Fatalf("replay changed the aggregate:\nbefore=%s\nafter =%s", summarizeAggregate(after), summarizeAggregate(again))
238		}
239	}
240	
241	// ensureSlowAggregate grows the store with irrelevant series until one
242	// aggregate call takes long enough to overlap deterministically with a
243	// concurrent ingestion. The filler series use another service, so the
244	// scenario query never includes them; they only widen the read scan.
245	func ensureSlowAggregate(t *testing.T, s *Store, query AggregateQuery) time.Duration {
246		t.Helper()
247		base := aggScenarioAnchor().AddDate(0, -1, 0)
248		scan := func() time.Duration {
249			start := time.Now()
250			if _, err := s.Aggregate(query); err != nil {
251				t.Fatalf("warmup aggregate: %v", err)
252			}
253			return time.Since(start)
254		}
255		total := 0
256		for round := 0; round < 6; round++ {
257			const chunk = 40000
258			fillers := make([]Sample, 0, chunk)
259			for i := range chunk {
260				id := strconv.Itoa(total + i)
261				fillers = append(fillers, Sample{
262					ID:      "filler-" + id,
263					Service: "filler-svc",
264					Name:    "requests",
265					At:      base.Add(time.Duration(total+i) * time.Nanosecond),
266					Value:   float64(total + i),
267					Labels:  map[string]string{"i": id},
268				})
269			}
270			if _, err := s.Ingest(fillers, noopCommit); err != nil {
271				t.Fatalf("seed fillers: %v", err)
272			}
273			total += chunk
274			var slowest time.Duration
275			for range 3 {
276				if d := scan(); d > slowest {
277					slowest = d
278				}
279			}
280			if slowest >= 5*time.Millisecond {
281				return slowest
282			}
283		}
284		return scan()
285	}
286	
287	// TestAggregateOverlappingBatchCommitIsOneSnapshot overlaps aggregate reads
288	// with a whole-batch submission held inside its durable commit:
289	//
290	//   - An aggregate already scanning when the submission takes the store write
291	//     lock finishes with the complete pre-submission state.
292	//   - Every aggregate whose read lock is queued while the commit hook is held
293	//     waits (that wait is not an error) and returns the complete
294	//     post-submission state.
295	//
296	// Either way a single response may reflect only the full batch or none of it:
297	// no partial series set, no segment whose count/delta comes from the other
298	// state — even though the deltas summed across every series and segment
299	// happen to coincide before and after (100 in both), the per-series and
300	// per-segment values still must not be spliced.
301	func TestAggregateOverlappingBatchCommitIsOneSnapshot(t *testing.T) {
302		s := NewStore()
303		query := aggScenarioQuery()
304		if _, err := s.Ingest(scenarioSeedSamples(), nil); err != nil {
305			t.Fatalf("seed: %v", err)
306		}
307	
308		before, err := s.Aggregate(query)
309		if err != nil {
310			t.Fatalf("aggregate before: %v", err)
311		}
312		assertScenarioResult(t, before, []string{"1", "2"}, beforeCounts, beforeDeltas)
313		scanTime := ensureSlowAggregate(t, s, query)
314	
315		earlyDone := make(chan []AggregateSeries, 1)
316		go func() {
317			got, err := s.Aggregate(query)
318			if err != nil {
319				t.Errorf("early aggregate: %v", err)
320				return
321			}
322			earlyDone <- got
323		}()
324		// Start the submission while the slow aggregate is (almost certainly)
325		// mid-scan; the assertions below hold for either scheduling outcome.
326		time.Sleep(scanTime / 2)
327	
328		entered := make(chan struct{})
329		release := make(chan struct{})
330		ingestDone := make(chan struct{})
331		go func() {
332			defer close(ingestDone)
333			result, err := s.Ingest(scenarioBatchSamples(), func(persisted []Sample) error {
334				close(entered)
335				<-release
336				return nil
337			})
338			if err != nil {
339				t.Errorf("blocked ingest: %v", err)
340				return
341			}
342			if result.Created != 11 {
343				t.Errorf("batch created=%d, want 11", result.Created)
344			}
345		}()
346		<-entered
347	
348		// The commit hook holds the write lock now; these aggregates queue behind
349		// it, wait for the commit, and scan only afterwards.
350		const readers = 24
351		observed := make(chan []AggregateSeries, readers)
352		var wg sync.WaitGroup
353		for range readers {
354			wg.Add(1)
355			go func() {
356				defer wg.Done()
357				got, err := s.Aggregate(query)
358				if err != nil {
359					t.Errorf("queued aggregate: %v", err)
360					return
361				}
362				observed <- got
363			}()
364		}
365		// Give the reads time to pile onto the pending write lock; the guarantee
366		// does not depend on this delay, it only widens coverage.
367		time.Sleep(20 * time.Millisecond)
368		close(release)
369		<-ingestDone
370		wg.Wait()
371		close(observed)
372	
373		after, err := s.Aggregate(query)
374		if err != nil {
375			t.Fatalf("aggregate after: %v", err)
376		}
377		assertScenarioResult(t, after, []string{"1", "2", "3"}, afterCounts, afterDeltas)
378		if reflect.DeepEqual(before, after) {
379			t.Fatal("pre- and post-batch aggregates must differ")
380		}
381	
382		count := 0
383		for got := range observed {
384			count++
385			if !reflect.DeepEqual(got, after) {
386				t.Fatalf("queued aggregate must show the whole post-batch state:\n%v\nwant:\n%v",
387					summarizeAggregate(got), summarizeAggregate(after))
388			}
389		}
390		if count != readers {
391			t.Fatalf("collected %d queued aggregates, want %d", count, readers)
392		}
393	
394		// The aggregate in flight when the submission started must be exactly one
395		// committed dataset: fully pre-batch or fully post-batch.
396		early := <-earlyDone
397		pre := reflect.DeepEqual(early, before)
398		post := reflect.DeepEqual(early, after)
399		if !pre && !post {
400			t.Fatalf("overlapping aggregate must be the complete pre- or post-batch state, got a splice:\n%v",
401				summarizeAggregate(early))
402		}
403	}
404	
405	// TestAggregateUnchangedAfterConflictBatch covers the 409 contract for
406	// aggregation: one sample with a different id claiming a stored series at the
407	// same absolute instant rejects the whole batch, so none of its other valid
408	// samples may appear and every segment stays at its pre-submission result.
409	func TestAggregateUnchangedAfterConflictBatch(t *testing.T) {
410		s := NewStore()
411		query := aggScenarioQuery()
412		if _, err := s.Ingest(scenarioSeedSamples(), nil); err != nil {
413			t.Fatalf("seed: %v", err)
414		}
415	
416		before, err := s.Aggregate(query)
417		if err != nil {
418			t.Fatalf("aggregate before: %v", err)
419		}
420	
421		if _, err := s.Ingest(scenarioConflictBatchSamples(), noopCommit); !IsConflictError(err) {
422			t.Fatalf("series/time clash must be a conflict, got %v", err)
423		}
424		after, err := s.Aggregate(query)
425		if err != nil {
426			t.Fatalf("aggregate after conflict: %v", err)
427		}
428		if !reflect.DeepEqual(after, before) {
429			t.Fatalf("409 batch must leave the aggregate untouched:\nbefore=%s\nafter =%s",
430				summarizeAggregate(before), summarizeAggregate(after))
431		}
432	
433		// A repeated id inside one otherwise-valid batch is rejected wholesale
434		// too; append a duplicate of one of the batch's own samples.
435		dup := append([]Sample(nil), scenarioBatchSamples()...)
436		dup = append(dup, scenarioBatchSamples()[0])
437		if _, err := s.Ingest(dup, noopCommit); !IsConflictError(err) {
438			t.Fatalf("repeated id within batch must be a conflict, got %v", err)
439		}
440		again, err := s.Aggregate(query)
441		if err != nil {
442			t.Fatalf("aggregate after duplicate batch: %v", err)
443		}
444		if !reflect.DeepEqual(again, before) {
445			t.Fatalf("duplicate-id batch must leave the aggregate untouched: %s", summarizeAggregate(again))
446		}
447	
448		// The untouched dataset still moves to the full post state once a valid
449		// batch commits, proving the equality checks above were discriminating.
450		if _, err := s.Ingest(scenarioBatchSamples(), noopCommit); err != nil {
451			t.Fatalf("valid batch after conflicts: %v", err)
452		}
453		committed, err := s.Aggregate(query)
454		if err != nil {
455			t.Fatalf("aggregate after valid batch: %v", err)
456		}
457		assertScenarioResult(t, committed, []string{"1", "2", "3"}, afterCounts, afterDeltas)
458	}
459

